import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        return (f"Error creating directories: {e}", [])

    zip_path = DOWNLOAD_DIR / filename

    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
        with open(zip_path, "wb") as f:
            f.write(response.content)
    except requests.RequestException as e:
        return (f"Error downloading file: {e}", [])
    except OSError as e:
        return (f"Error saving file: {e}", [])

    try:
        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)
    except (zipfile.BadZipFile, OSError) as e:
        return (f"Error extracting zip file: {e}", [])

    try:
        filenames = sorted(
            str(path.relative_to(ZIP_DIR))
            for path in ZIP_DIR.rglob("*")
            if path.is_file()
        )
    except OSError as e:
        return (f"Error reading extracted files: {e}", [])

    return (f"Successfully downloaded and extracted {filename}", filenames)

import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)

        zip_path = DOWNLOAD_DIR / filename

        response = requests.get(url, stream=True, verify=False)
        response.raise_for_status()

        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)

        with zipfile.ZipFile(zip_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)

        filenames = [
            str(path.relative_to(ZIP_DIR))
            for path in ZIP_DIR.rglob("*")
            if path.is_file()
        ]

        return "Download and extraction completed successfully.", filenames

    except requests.RequestException as e:
        return f"Error downloading file: {e}", []
    except (OSError, zipfile.BadZipFile, zipfile.LargeZipFile) as e:
        return f"Error handling or extracting file: {e}", []

