import requests
import pandas as pd
def task_func(api_url):
    if not isinstance(api_url, str):
        raise TypeError("api_url must be a string.")

    try:
        response = requests.get(api_url, verify=False)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as e:
        raise requests.HTTPError(f"API request failed: {e}") from e
    except ValueError as e:
        raise requests.HTTPError(f"Invalid JSON response: {e}") from e

    try:
        df = pd.json_normalize(data)
    except Exception as e:
        raise requests.HTTPError(f"Invalid response data: {e}") from e

    if df.empty:
        return df, None

    import matplotlib.pyplot as plt

    _, ax = plt.subplots()
    numeric_df = df.select_dtypes(include="number")

    if not numeric_df.empty:
        numeric_df.plot(ax=ax)
    else:
        ax.plot(range(len(df)), [1] * len(df), marker="o")

    return df, ax

