    if webpage_url.startswith(("http://", "https://")):
        try:
            response = requests.get(webpage_url, verify=False)
            response.raise_for_status()
            content = response.content
        except requests.RequestException:
            raise
    else:
        with open(webpage_url, "rb") as f:
            content = f.read()

    try:
        document = html.fromstring(content)
        tables = document.xpath("//table")
    except Exception:
        return 0

    if not tables:
        return 0

    table_html = html.tostring(tables[0], encoding="unicode")

    try:
        dataframes = pd.read_html(table_html)
    except ValueError:
        return 0

    if not dataframes:
        return 0

    df = dataframes[0]

    if df.empty:
        return 0

    try:
        with sqlite3.connect(database_name) as conn:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
    except sqlite3.DatabaseError:
        raise

    return len(df)

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if webpage_url.startswith(("http://", "https://")):
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
        content = response.text
    else:
        path = webpage_url[7:] if webpage_url.startswith("file://") else webpage_url
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()

    try:
        tables = pd.read_html(content, flavor="lxml")
    except ValueError:
        return 0

    if not tables:
        return 0

    df = tables[0]

    if df.empty:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        try:
            df.to_sql("my_table", conn, if_exists="replace", index=False)
            conn.commit()
        finally:
            conn.close()
    except sqlite3.DatabaseError:
        raise

    return len(df)

