import requests
import logging
def task_func(repo_url: str) -> dict:
    open_issues_threshold = 100

    try:
        response = requests.get(repo_url, verify=False, timeout=10)

        if response.status_code == 403 and response.headers.get("X-RateLimit-Remaining") == "0":
            raise requests.exceptions.HTTPError(
                "GitHub API rate limit exceeded.",
                response=response
            )

        response.raise_for_status()

        try:
            repo_info = response.json()
        except ValueError as e:
            raise requests.exceptions.RequestException(f"Invalid JSON response: {e}") from e

        open_issues = repo_info.get("open_issues_count", 0)
        if open_issues > open_issues_threshold:
            logging.warning(
                "Repository has a large number of open issues: %s",
                open_issues
            )

        return repo_info

    except requests.exceptions.HTTPError:
        raise
    except requests.exceptions.RequestException:
        raise

