import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except requests.RequestException:
        return []

    try:
        soup = BeautifulSoup(response.text, "html.parser")
        result = []

        def try_evaluate(value):
            try:
                evaluated = ast.literal_eval(value.strip())
                if isinstance(evaluated, dict):
                    result.append(evaluated)
                elif isinstance(evaluated, str):
                    try:
                        nested = ast.literal_eval(evaluated.strip())
                        if isinstance(nested, dict):
                            result.append(nested)
                    except Exception:
                        pass
            except Exception:
                pass

        for script in soup.find_all("script"):
            content = script.string if script.string is not None else script.get_text()
            if not content:
                continue

            stripped = content.strip()
            try_evaluate(stripped)

            starts = []
            for i, char in enumerate(content):
                if char == "{":
                    starts.append(i)
                elif char == "}" and starts:
                    start = starts.pop()
                    candidate = content[start:i + 1]
                    try_evaluate(candidate)

        return result
    except Exception:
        return []

