            for candidate in candidates:
                candidate = candidate.strip()
                if not candidate or candidate in seen:
                    continue
                seen.add(candidate)

                try:
                    value = ast.literal_eval(candidate)
                    if isinstance(value, dict):
                        dictionaries.append(value)
                except Exception:
                    continue

        return dictionaries
    except Exception:
        return []

