import collections
import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    repos = []
    url = API_URL.rstrip('/') + '/' + str(user) + '/repos'
    params = {'per_page': 100}

    while url:
        response = requests.get(url, params=params, verify=False)
        response.raise_for_status()

        try:
            data = response.json()
        except ValueError:
            data = json.loads(response.text)

        if isinstance(data, list):
            repos.extend(data)

        link_header = response.headers.get('Link', '') if hasattr(response, 'headers') else ''
        next_url = None

        for part in link_header.split(','):
            section = part.strip()
            if 'rel="next"' in section:
                start = section.find('<')
                end = section.find('>')
                if start != -1 and end != -1:
                    next_url = section[start + 1:end]
                break

        url = next_url
        params = None

    sorted_repos = sorted(
        repos,
        key=lambda repo: repo.get('created_at', '')
    )

    return [repo.get('name') for repo in sorted_repos if repo.get('name') is not None]

