import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url.strip():
        raise Exception("Invalid URL.")

    try:
        response = requests.get(url, params=parameters, headers=HEADERS, verify=False)
        response.raise_for_status()
    except Exception as e:
        raise Exception(f"URL cannot be accessed: {e}")

    try:
        data = response.json()
    except Exception as e:
        raise Exception(f"Invalid data: {e}")

    if data is None or data == [] or data == {}:
        raise Exception("Empty data.")

    try:
        if isinstance(data, dict):
            extracted = None
            for key in ("data", "results", "items", "records"):
                if key in data and isinstance(data[key], list):
                    extracted = data[key]
                    break
            if extracted is not None:
                df = pd.DataFrame(extracted)
            else:
                df = pd.json_normalize(data)
        elif isinstance(data, list):
            df = pd.DataFrame(data)
        else:
            raise Exception("Invalid data format.")

        if df.empty:
            raise Exception("Empty data.")

        numeric_df = df.select_dtypes(include="number")
        if numeric_df.empty:
            raise Exception("No numerical data available for correlation.")

        corr = numeric_df.corr()
        ax = sns.heatmap(corr, annot=True, cmap="coolwarm")
        ax.figure.show()

        return df, ax
    except Exception as e:
        raise Exception(f"Invalid data: {e}")

